def solve(grid):
    """Count islands in a possibly jagged binary grid.
    Adjacent cells are those sharing an edge (up, down, left, right).
    """
    if not grid:
        return 0
    visited = set()
    rows = len(grid)
    def neighbors(r, c):
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < rows and 0 <= nc < len(grid[nr]):
                yield nr, nc
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
