    import bisect
    if not nums:
        return 0
    # tails[i] = smallest possible tail value of an increasing subsequence of length i+1
    tails = []
    for x in nums:
        # find location to replace in tails
        idx = bisect.bisect_left(tails, x)
        # for strictly increasing, we need to replace first >= x
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

