def solve(s):
    """Run‑length encode *s*.
    Returns a list of [value, count] pairs. Handles strings and bytes.
    """
    if not s:
        return []
    # If bytes or bytearray, decode to string
    if isinstance(s, (bytes, bytearray)):
        try:
            s = s.decode()
        except Exception:
            # fallback: treat each byte as a character via chr
            s = ''.join(chr(b) for b in s)
    # Ensure we have a sequence we can index
    seq = list(s)
    if not seq:
        return []
    res = []
    prev = seq[0]
    cnt = 1
    for ch in seq[1:]:
        if ch == prev:
            cnt += 1
        else:
            res.append([prev, cnt])
            prev = ch
            cnt = 1
    res.append([prev, cnt])
    return res

def solve(s: str) -> int:
    """Convert a Roman numeral to an integer.
