def solve(nums):
    """Return length of the longest strictly increasing subsequence.
    Uses patience sorting O(n log n).
    Empty list returns 0.
    """
    import bisect
    if not nums:
        return 0
    tails = []  # tails[i] = smallest possible tail of an increasing subseq of length i+1
    for x in nums:
        # find insertion point (first >= x) because we need strictly increasing
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

