def solve(a, b):
    """Compute Levenshtein distance between strings a and b.
    Uses O(len(a)*len(b)) DP.
    """
    # Ensure inputs are strings; if not, convert to str
    if not isinstance(a, str):
        a = str(a)
    if not isinstance(b, str):
        b = str(b)
    n, m = len(a), len(b)
    # dp[i][j] = distance between a[:i] and b[:j]
    dp = [[0]*(m+1) for _ in range(n+1)]
    for i in range(n+1):
        dp[i][0] = i
    for j in range(m+1):
        dp[0][j] = j
    for i in range(1, n+1):
        for j in range(1, m+1):
            if a[i-1] == b[j-1]:
                cost = 0
            else:
                cost = 1
            dp[i][j] = min(
                dp[i-1][j] + 1,      # deletion
                dp[i][j-1] + 1,      # insertion
                dp[i-1][j-1] + cost  # substitution
            )
    return dp[n][m]

